class Solution:
    def countWords(self, words1: List[str], words2: List[str]) -> int:
        count = 0
        seen = set()
        for w in words1:
            if w in seen:
                continue
            seen.add(w)
            if words1.count(w) == 1 and words2.count(w) == 1:
                count += 1
        return count

