class Solution {
public:
    int countWords(vector<string>& words1, vector<string>& words2) {
        int count = 0;
        unordered_set<string> seen;
        for (auto& w : words1) {
            if (seen.count(w)) continue;
            seen.insert(w);
            if (std::count(words1.begin(), words1.end(), w) == 1 &&
                std::count(words2.begin(), words2.end(), w) == 1)
                count++;
        }
        return count;
    }
};

