class Solution {
    public int countWords(String[] words1, String[] words2) {
        int count = 0;
        Set<String> seen = new HashSet<>();
        for (String w : words1) {
            if (!seen.add(w)) continue;
            if (countOf(words1, w) == 1 && countOf(words2, w) == 1) count++;
        }
        return count;
    }

    private int countOf(String[] words, String target) {
        int c = 0;
        for (String w : words)
            if (w.equals(target)) c++;
        return c;
    }
};

